import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D9E58p8B.js";const p=JSON.parse('{"title":"Showing what is happening","description":"","frontmatter":{"title":"Showing what is happening"},"headers":[],"relativePath":"en/agent/montrer.md","filePath":"en/agent/montrer.md"}'),n={name:"en/agent/montrer.md"};function h(s,e,l,i,d,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="showing-what-is-happening" tabindex="-1">Showing what is happening <a class="header-anchor" href="#showing-what-is-happening" aria-label="Permalink to &quot;Showing what is happening&quot;">​</a></h1><p>When an agent acts on your screen, you want to see what it is doing. The Overlay draws markers on top of the screen.</p><h2 id="what-you-ask" tabindex="-1">What you ask <a class="header-anchor" href="#what-you-ask" aria-label="Permalink to &quot;What you ask&quot;">​</a></h2><blockquote><p>&quot;Show me what you are doing while you fill in the form.&quot;</p></blockquote><h2 id="before-turn-on-on-screen-presence" tabindex="-1">Before: turn on on-screen presence <a class="header-anchor" href="#before-turn-on-on-screen-presence" aria-label="Permalink to &quot;Before: turn on on-screen presence&quot;">​</a></h2><p>The Overlay is <strong>off by default</strong>. Turn on <strong>Présence à l&#39;écran</strong> (On-screen presence) in the panel. While this setting is off, the <code>overlay_*</code> tools answer <code>ok</code> but display nothing: the order is dropped.</p><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Effect</th></tr></thead><tbody><tr><td><a href="/Daimon/en/reference/overlay.html#overlay-highlight"><code>overlay_highlight</code></a></td><td>Rounded frame around a region, with a label</td></tr><tr><td><a href="/Daimon/en/reference/overlay.html#overlay-spotlight"><code>overlay_spotlight</code></a></td><td>Darkens the screen except one region</td></tr><tr><td><a href="/Daimon/en/reference/overlay.html#overlay-cursor"><code>overlay_cursor</code></a></td><td>Cursor halo</td></tr><tr><td><a href="/Daimon/en/reference/overlay.html#overlay-banner"><code>overlay_banner</code></a></td><td>Banner colored by level (<code>L1</code> to <code>L4</code>, <code>gate</code>), with a text</td></tr><tr><td><a href="/Daimon/en/reference/overlay.html#overlay-clear"><code>overlay_clear</code></a></td><td>Clears all marks</td></tr></tbody></table><p>These tools are presentation only: no level, no effect on the system. Coordinates are <strong>global pixels</strong>, already resolved by the agent.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>The markers appear on your screen while the agent works. <strong>They appear in no screenshot</strong>: this is intentional, so that the agent does not read itself.</p><h2 id="if-nothing-appears" tabindex="-1">If nothing appears <a class="header-anchor" href="#if-nothing-appears" aria-label="Permalink to &quot;If nothing appears&quot;">​</a></h2><ol><li>Check that <strong>Présence à l&#39;écran</strong> is turned on.</li><li>Ask the agent to call <code>daimon_doctor</code> and read the <code>overlay</code> key: <code>listening</code> says whether the drawing process is alive and listening, <code>last_log_line</code> gives its last trace.</li><li>The process restarts by itself on the next call as long as presence is on. Detail: <a href="/Daimon/en/reference/overlay.html#helper">Overlay</a>.</li></ol><p>Next: <a href="/Daimon/en/agent/deleguer.html">Delegating to a sub-agent</a>.</p>',14)])])}const f=t(n,[["render",h]]);export{p as __pageData,f as default};
